CREATE TABLE "marketplace_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(80) NOT NULL, "slug" varchar(80) NOT NULL UNIQUE, "description" text NOT NULL);
CREATE TABLE "marketplace_connectedaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "stripe_account_id" varchar(255) NOT NULL UNIQUE, "transfers_status" varchar(32) NOT NULL, "payouts_status" varchar(32) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "marketplace_listing" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "slug" varchar(180) NOT NULL UNIQUE, "description" text NOT NULL, "price_cents" integer unsigned NOT NULL CHECK ("price_cents" >= 0), "currency" varchar(3) NOT NULL, "published" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" bigint NOT NULL REFERENCES "marketplace_category" ("id") DEFERRABLE INITIALLY DEFERRED, "game_id" bigint NOT NULL UNIQUE REFERENCES "games_game" ("id") DEFERRABLE INITIALLY DEFERRED, "seller_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "marketplace_payout" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "amount_cents" integer unsigned NOT NULL CHECK ("amount_cents" >= 0), "reversed_cents" integer unsigned NOT NULL CHECK ("reversed_cents" >= 0), "currency" varchar(3) NOT NULL, "status" varchar(16) NOT NULL, "stripe_transfer_id" varchar(255) NOT NULL UNIQUE, "idempotency_key" varchar(255) NOT NULL UNIQUE, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "creator_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "marketplace_purchase" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(160) NOT NULL, "price_cents" integer unsigned NOT NULL CHECK ("price_cents" >= 0), "currency" varchar(3) NOT NULL, "platform_fee_cents" integer unsigned NOT NULL CHECK ("platform_fee_cents" >= 0), "processing_estimate_cents" integer unsigned NOT NULL CHECK ("processing_estimate_cents" >= 0), "creator_credit_cents" integer unsigned NOT NULL CHECK ("creator_credit_cents" >= 0), "refunded_cents" integer unsigned NOT NULL CHECK ("refunded_cents" >= 0), "disputed_cents" integer unsigned NOT NULL CHECK ("disputed_cents" >= 0), "status" varchar(16) NOT NULL, "stripe_checkout_session_id" varchar(255) NOT NULL, "stripe_payment_intent_id" varchar(255) NOT NULL, "stripe_charge_id" varchar(255) NOT NULL, "paid_at" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "buyer_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "game_id" bigint NULL REFERENCES "games_game" ("id") DEFERRABLE INITIALLY DEFERRED, "listing_id" bigint NULL REFERENCES "marketplace_listing" ("id") DEFERRABLE INITIALLY DEFERRED, "seller_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "marketplace_earning" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "credit_cents" integer unsigned NOT NULL CHECK ("credit_cents" >= 0), "unpaid_cents" integer unsigned NOT NULL CHECK ("unpaid_cents" >= 0), "settled_cents" integer unsigned NOT NULL CHECK ("settled_cents" >= 0), "reversed_cents" integer unsigned NOT NULL CHECK ("reversed_cents" >= 0), "status" varchar(16) NOT NULL, "available_at" datetime NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "creator_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "payout_id" bigint NULL REFERENCES "marketplace_payout" ("id") DEFERRABLE INITIALLY DEFERRED, "purchase_id" bigint NOT NULL UNIQUE REFERENCES "marketplace_purchase" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "marketplace_listingtag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(24) NOT NULL, "listing_id" bigint NOT NULL REFERENCES "marketplace_listing" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_listing_tag" UNIQUE ("listing_id", "name"));
CREATE UNIQUE INDEX "uniq_marketplace_purchase_per_game" ON "marketplace_purchase" ("buyer_id", "game_id") WHERE "status" IN ('pending', 'paid', 'refunded', 'disputed');
CREATE INDEX "marketplace_listing_category_id_cab5ec78" ON "marketplace_listing" ("category_id");
CREATE INDEX "marketplace_listing_seller_id_56a0f16d" ON "marketplace_listing" ("seller_id");
CREATE INDEX "marketplace_payout_creator_id_6a20c109" ON "marketplace_payout" ("creator_id");
CREATE INDEX "marketplace_purchase_buyer_id_2710e1f6" ON "marketplace_purchase" ("buyer_id");
CREATE INDEX "marketplace_purchase_game_id_b7f0b283" ON "marketplace_purchase" ("game_id");
CREATE INDEX "marketplace_purchase_listing_id_c48ac7b9" ON "marketplace_purchase" ("listing_id");
CREATE INDEX "marketplace_purchase_seller_id_a0a9b5b8" ON "marketplace_purchase" ("seller_id");
CREATE INDEX "marketplace_earning_creator_id_47171526" ON "marketplace_earning" ("creator_id");
CREATE INDEX "marketplace_earning_payout_id_301c98fe" ON "marketplace_earning" ("payout_id");
CREATE INDEX "marketplace_listingtag_name_9d15e4fa" ON "marketplace_listingtag" ("name");
CREATE INDEX "marketplace_listingtag_listing_id_3d1ffd93" ON "marketplace_listingtag" ("listing_id");
